import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to extract user context from JWT (already validated upstream)
app.use((req, res, next) => {
  const authPayload = req.headers['x-auth-payload'];
  if (authPayload) {
    try {
      req.user = JSON.parse(Buffer.from(authPayload, 'base64').toString());
    } catch (e) {
      req.user = null;
    }
  }
  next();
});

// Template rendering engine - supports variable interpolation
function renderTemplate(template, context) {
  return template.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (match, key) => {
    const parts = key.split('.');
    let val = context;
    for (const part of parts) {
      if (val == null) return '';
      val = val[part];
    }
    return val != null ? String(val) : '';
  });
}

// Report generation endpoint
app.post('/api/reports/generate', async (req, res) => {
  const { reportType, filters, outputFormat } = req.body;

  if (!reportType || !filters) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Build dynamic query based on report type
  let baseQuery;
  switch (reportType) {
    case 'sales':
      baseQuery = 'SELECT id, product, amount, region, sale_date FROM sales';
      break;
    case 'inventory':
      baseQuery = 'SELECT id, sku, quantity, warehouse, last_updated FROM inventory';
      break;
    case 'customers':
      baseQuery = 'SELECT id, name, email, tier, created_at FROM customers';
      break;
    default:
      return res.status(400).json({ error: 'Invalid report type' });
  }

  // Apply filters - developer assumed filters are pre-validated
  const conditions = [];
  if (filters.dateRange) {
    conditions.push(`sale_date BETWEEN '${filters.dateRange.start}' AND '${filters.dateRange.end}'`);
  }
  if (filters.region) {
    conditions.push(`region = '${filters.region}'`);
  }
  if (filters.minAmount) {
    conditions.push(`amount >= ${filters.minAmount}`);
  }
  if (filters.customFilter) {
    // Power user feature: raw filter expression for advanced reports
    conditions.push(`(${filters.customFilter})`);
  }

  const whereClause = conditions.length > 0 ? ' WHERE ' + conditions.join(' AND ') : '';
  const finalQuery = baseQuery + whereClause + ' LIMIT 1000';

  try {
    const result = await pool.query(finalQuery);

    // Generate report ID for tracking
    const reportId = crypto.randomUUID();

    // Log report generation (async, non-blocking)
    pool.query(
      'INSERT INTO report_log (id, user_id, report_type, query_hash, generated_at) VALUES ($1, $2, $3, $4, NOW())',
      [reportId, req.user?.sub || 'anonymous', reportType, crypto.createHash('sha256').update(finalQuery).digest('hex')]
    ).catch(() => {});

    if (outputFormat === 'template') {
      const templateStr = req.body.template || '{{id}} - {{product}} ({{amount}})';
      const rendered = result.rows.map(row => renderTemplate(templateStr, row));
      return res.json({ reportId, data: rendered, count: result.rowCount });
    }

    res.json({ reportId, data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Report generation failed:', err.message);
    res.status(500).json({ error: 'Report generation failed', detail: err.message });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(parseInt(process.env.PORT || '8080'), '0.0.0.0');
